import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadManifest, writeGenerated } from "./lib/skills.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const manifest = await loadManifest(root);
const byName = new Map(manifest.skills.map((skill) => [skill.name, skill]));

const lines = [
  "# Skill graph",
  "",
  "Edges point from a skill to skills it hands work to. Generated by `npm run graph`.",
  "",
  "```mermaid",
  "graph TD",
  ...manifest.skills.map(
    (skill) => `  ${skill.name}["${skill.name}<br/>${skill.category}"]`,
  ),
  ...manifest.skills.flatMap((skill) =>
    (skill.related || []).map((related) => `  ${skill.name} --> ${related}`),
  ),
  "```",
  "",
  "## Cycles",
  "",
];

const state = new Map();
const stack = [];
const cycles = [];
function visit(name) {
  if (state.get(name) === "done") return;
  if (state.get(name) === "visiting") {
    cycles.push([...stack.slice(stack.indexOf(name)), name].join(" -> "));
    return;
  }
  state.set(name, "visiting");
  stack.push(name);
  for (const related of byName.get(name)?.related || []) {
    if (byName.has(related)) visit(related);
  }
  stack.pop();
  state.set(name, "done");
}
for (const skill of manifest.skills) visit(skill.name);

lines.push(...(cycles.length ? cycles.map((cycle) => `- ${cycle}`) : ["None found."]), "");
await writeGenerated(root, "docs/skill-graph.md", lines.join("\n"));
console.log(cycles.length ? `FAIL: ${cycles.length} cycle(s)` : `OK: no cycles across ${manifest.skills.length} skills`);
if (cycles.length) process.exitCode = 1;
